def create_existing_project_milestones(apps, schema_editor):
    Project = apps.get_model("projects", "Project")
    MilestoneEvent = apps.get_model("milestones", "MilestoneEvent")
    database = schema_editor.connection.alias

    for project in Project.objects.using(database).iterator():
        MilestoneEvent.objects.using(database).create(
            project_id=project.pk,
            title="Project started",
            occurred_at=project.started_at,
        )
        if project.is_completed:
            MilestoneEvent.objects.using(database).create(
                project_id=project.pk,
                title="Project completed",
                occurred_at=project.completed_at or project.started_at,
            )


